import numpy as np

def problem(x: np.ndarray) -> float:
    """
    Synthetic benchmark function combining a skewed quadratic bowl with sinusoidal modulation and some pairwise interaction.
    The function is designed to exhibit specific Exploratory Landscape Analysis (ELA) characteristics.
    Formula: f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + pairwise_interaction(x)
    """
    def quadratic_bowl(x):
        """Skewed quadratic bowl."""
        return np.sum((x - 1)**2) + 0.3 * x[0]**3 # added skewness using a cubic term

    def sinusoidal_modulation(x):
        """Sinusoidal modulation."""
        return np.sum(np.sin(2 * x)) * 0.1 # Reduced amplitude for a subtle effect and increased variance for fitness_std

    def pairwise_interaction(x):
        """Pairwise interaction term."""
        interactions = 0
        for i in range(len(x)):
            for j in range(i + 1, len(x)):
                  interactions += x[i] * x[j] * 0.05 # Lower amplitude
        return interactions

    return quadratic_bowl(x) + sinusoidal_modulation(x) + pairwise_interaction(x)
